import{e as a,ab as o,a1 as n,m as i,r,p as s}from"./chunks/framework.BGh0NSIy.js";const w=JSON.parse(`{"title":"Why We're Here 🤍","description":"Help Heal","frontmatter":{"title":"Why We're Here 🤍","description":"Help Heal","date":"2025-09-11T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/WWH.md","filePath":"posts/WWH.md"}`),l={name:"posts/WWH.md"};function h(p,e,d,u,m,f){const t=o("Post");return n(),i("div",null,[r(t,{authors:"nbats"}),e[0]||(e[0]=s("<p>People always want to know what the point of life is. Why are they on earth? What are we doing here? Whats our purpose? <em>Whats the point?</em></p><p>For most of my life, I didn&#39;t really have any answer, but as I got older, I realized, things weren&#39;t about me. I took a step back, and recognized a much bigger picture we&#39;re all apart of, and I now know exactly why we&#39;re here on earth.</p><p>As a human, you have a powerful ability, to calm, heal, and help those around you. You have the ability to protect both the people in our world, and the planet itself from harm and distress.</p><p>I know there is a huge amount of pain in our world, a lot of anger, a lot of sadness, and believe me when I say, I share the same feelings. However I believe its important that we each learn to <em><strong>harness that energy into things that are positive and kind</strong></em>, not negative or evil.</p><p>Remember that a lot of who you are, is your ability to experience things outside of yourself, <em>including other humans.</em> They are a direct and immediate part of your own reality. Treat their struggles and woes as if they were your own, don&#39;t leave people behind, don&#39;t leave people unloved. As frustrating as the world can be, it is worth protecting, it is worth loving, it is worth healing together.</p><hr><ul><li><p><em>&quot;Life is a beautiful, magnificent thing, even to a jellyfish... The trouble is you won&#39;t fight. You&#39;ve given in, continually dwelling on sickness and death. But there&#39;s something just as inevitable as death, and that&#39;s life. Life, life, life. Think of all the power that&#39;s in the universe, moving the earth, growing the trees. That&#39;s the same power within you if you only have the courage and the will to use it.&quot;</em> - Charlie Chaplin, Limelight 1952</p></li><li><p><em>&quot;The wise man beholds all beings in the Self, and the Self in all beings; for that reason, he does not hate anyone.&quot;</em> - Isa Upanishad</p></li></ul>",7))])}const c=a(l,[["render",h]]);export{w as __pageData,c as default};
